def install_icons():
    dirs = [
        Path("docs/icons"),
    ]
    for d in dirs:
        d.mkdir(parents=True, exist_ok=True)
        for name, svg in ICONS.items():
            (d / name).write_text(svg.strip(), encoding="utf-8")
        print(f"Installed {len(ICONS)} icons into {d.resolve()}")

if __name__ == "__main__":
    install_icons()
